"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { ChatComposer } from "@/components/chat-composer";
import { SafeMarkdown } from "@/components/markdown";
import { analyticsApi } from "@/lib/api/analytics";
import { conversationsApi } from "@/lib/api/conversations";
import { ApiError } from "@/lib/api/client";
import type { AnalystRun, PublicRunEvent } from "@/types/analytics";
import type { Conversation, ConversationMessage } from "@/types/conversations";
import { statusFromEvent } from "./status";

type Message = Pick<ConversationMessage, "role" | "content" | "run_id">;

function groupConversations(conversations: Conversation[]) {
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const recent: Conversation[] = []; const previous: Conversation[] = [];
  conversations.forEach((conversation) => {
    const updatedAt = new Date(conversation.updated_at);
    (Number.isNaN(updatedAt.getTime()) || updatedAt >= today ? recent : previous).push(conversation);
  });
  return [{ label: "Today", items: recent }, { label: "Previous", items: previous }].filter((group) => group.items.length > 0);
}

export function Workbench() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [status, setStatus] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [conversationId, setConversationId] = useState<string | null>(null);
  const [historyError, setHistoryError] = useState<string | null>(null);
  const source = useRef<EventSource | null>(null);
  const terminalRun = useRef<string | null>(null);
  const finishing = useRef(false);
  const conversationGroups = useMemo(() => groupConversations(conversations), [conversations]);

  const loadConversations = async () => {
    try { const page = await conversationsApi.list(); setConversations(page.items); setHistoryError(null); }
    catch { setHistoryError("Conversation history could not be loaded."); }
  };
  useEffect(() => { const timer = window.setTimeout(() => { void loadConversations(); }, 0); return () => window.clearTimeout(timer); }, []);

  const switchConversation = async (id: string) => {
    source.current?.close(); terminalRun.current = null; finishing.current = false; setStatus(null); setError(null);
    try { const conversation = await conversationsApi.get(id); setConversationId(conversation.id); setMessages(conversation.messages.map((message) => ({ role: message.role, content: message.content, run_id: message.run_id }))); }
    catch { setHistoryError("Conversation could not be loaded."); }
  };
  const finish = async (runId: string) => {
    if (finishing.current) return;
    finishing.current = true;
    let run: AnalystRun | undefined;
    for (let attempt = 0; attempt < 8; attempt += 1) { run = await analyticsApi.getRun(runId); if (run.status !== "running") break; await new Promise((resolve) => window.setTimeout(resolve, 100)); }
    if (!run) throw new Error("The run result was unavailable.");
    if (run.status === "completed" && run.final_response) setMessages((current) => [...current, { role: "assistant", content: run.final_response!, run_id: runId }]);
    else setError(run.error ?? "The analyst run ended without an answer.");
    setStatus(null); source.current?.close(); source.current = null; void loadConversations();
  };
  const submit = async (message: string) => {
    terminalRun.current = null; finishing.current = false; setError(null); setStatus("Analyzing…"); setMessages((current) => [...current, { role: "user", content: message, run_id: null }]);
    try {
      const created = await analyticsApi.createRun({ message, ...(conversationId ? { conversation_id: conversationId } : {}) });
      setConversationId(created.conversation_id); void loadConversations();
      source.current = analyticsApi.connect(created.run_id, (event: PublicRunEvent) => {
        setStatus(statusFromEvent(event));
        if (event.type === "run.completed") { terminalRun.current = created.run_id; void finish(created.run_id); }
        if (event.type === "run.failed") { terminalRun.current = created.run_id; setError(typeof event.data.error === "string" ? event.data.error : "The analyst run failed."); setStatus(null); source.current?.close(); void loadConversations(); }
      }, () => { if (terminalRun.current === created.run_id) return; setError("The progress stream disconnected. Checking the run status…"); void finish(created.run_id).catch(() => setStatus(null)); });
    } catch (cause) { setStatus(null); setError(cause instanceof ApiError ? cause.message : "Unable to start the analyst run."); }
  };
  const newConversation = async () => {
    source.current?.close(); terminalRun.current = null; finishing.current = false; setMessages([]); setStatus(null); setError(null);
    try { const conversation = await conversationsApi.create(); setConversationId(conversation.id); setConversations((current) => [conversation, ...current]); }
    catch { setHistoryError("A new conversation could not be created."); }
  };

  return <main className="workbench">
    <aside className="sidebar">
      <div><span className="eyebrow">WORKBENCH</span><h1>AI Data Analyst</h1></div>
      <button className="new-conversation" onClick={() => void newConversation()}>＋ New conversation</button>
      <section><p>CONVERSATIONS</p>{historyError && <span className="muted" role="alert">{historyError}</span>}{!historyError && conversations.length === 0 && <span className="muted">No saved conversations yet.</span>}
        <nav className="conversation-groups" aria-label="Conversations">{conversationGroups.map((group) => <div className="conversation-group" key={group.label}><h3>{group.label}</h3><div className="conversation-list">{group.items.map((conversation) => <button key={conversation.id} className={conversation.id === conversationId ? "active" : ""} onClick={() => void switchConversation(conversation.id)} title={conversation.title}>{conversation.title}</button>)}</div></div>)}</nav>
      </section>
    </aside>
    <section className="conversation"><header><div><span className="eyebrow">ANALYSIS SESSION</span><h2>AI Data Analyst</h2></div><span className="connection">● Backend connected</span></header>
      <div className="messages" aria-live="polite">{messages.length === 0 && !status && <div className="empty"><h3>Ask a question about your data</h3><p>Try investigating revenue changes, customer behavior, conversion, or operational performance.</p></div>}{messages.map((message, index) => <article className={`message ${message.role}`} data-run-id={message.run_id ?? undefined} key={`${message.run_id ?? "message"}-${index}`}>{message.role === "assistant" ? <SafeMarkdown content={message.content} /> : message.content}</article>)}{status && <div className="progress"><span className="spinner" />{status}</div>}{error && <div className="error" role="alert">{error}</div>}</div>
      <ChatComposer onSubmit={submit} disabled={Boolean(status)} />
    </section>
  </main>;
}
